<?php require_once 'config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Enter a name, valid email, and password of at least 8 characters.';else{$s=$conn->prepare('SELECT id FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();if($s->get_result()->num_rows)$error='Email already registered.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"user")');$s->bind_param('sss',$name,$email,$hash);if($s->execute()){header('Location: login.php?registered=1');exit;}$error='Registration failed.';}}}$page_title='Register';include 'header.php';?>
<div class="form"><h1>Create account</h1><?php if($error): ?><p class="error"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (8+ characters)<input type="password" name="password" minlength="8" required></label><button>Register</button></form><p>Already registered? <a href="login.php">Login</a></p></div><?php include 'footer.php'; ?>